/* @lc app=leetcode id=3962 lang=kotlin */ class Solution { tailrec fun ad(b: IntArray, i: Int, d: Int): Unit { if (i < b.size) ad(b.also { it[i] += d }, i + (i and -i), d) } tailrec fun ads(b: LongArray, i: Int, d: Long): Unit { if (i < b.size) ads(b.also { it[i] += d }, i + (i and -i), d) } tailrec fun qs(b: LongArray, i: Int, a: Long = 0L): Long { return if (i <= 0) a else qs(b, i - (i and -i), a + b[i]) } tailrec fun kth(b: IntArray, pos: Int, rem: Int, step: Int): Int { return if (step == 0) pos + 1 else if (pos + step < b.size && b[pos + step] < rem) kth(b, pos + step, rem - b[pos + step], step shr 1) else kth(b, pos, rem, step shr 1) } fun maxSum(nums: IntArray, k: Int): Long = nums.size.let { n -> Integer.highestOneBit(n).let { hi -> nums.indices.sortedWith(compareBy({ nums[it] }, { it })).let { ord -> IntArray(n).also { rk -> ord.forEachIndexed { t, id -> rk[id] = t + 1 } }.let { rk -> LongArray(n + 1).also { V -> ord.forEachIndexed { t, id -> V[t + 1] = nums[id].toLong() } }.let { V -> V.runningFold(0L) { a, b -> a + b }.drop(1).toLongArray().let { Pt -> nums.indices.maxOf { i -> IntArray(n + 1) { it and -it }.let { cO -> IntArray(n + 1).let { cI -> LongArray(n + 1).let { sI -> (i until n).fold(Triple(0, 0L, Long.MIN_VALUE)) { (pc, tin, best), j -> ad(cI, rk[j], 1).also { ad(cO, rk[j], -1) }.also { ads(sI, rk[j], nums[j].toLong()) }.let { (tin + nums[j]).let { nt -> (j - i + 1).let { inC -> (n - inC).let { outC -> minOf(k, inC, outC).let { lim -> { t: Int -> V[kth(cO, 0, outC - t + 1, hi)] > V[kth(cI, 0, t, hi)] }.let { cond -> generateSequence(minOf(pc, lim)) { it - 1 }.first { t -> t == 0 || cond(t) }.let { c1 -> generateSequence(c1) { it + 1 }.first { t -> t >= lim || !cond(t + 1) }.let { c -> Triple(c, nt, maxOf(best, nt + (if (c == 0) 0L else qs(sI, kth(cI, 0, c, hi)).let { sumIn -> kth(cO, 0, outC - c + 1, hi).let { q -> (Pt[n] - nt) - (Pt[q - 1] - qs(sI, q - 1)) - sumIn } }))) } } } } } } } } }.third } } } } } } } } } } }